/*
 * Data-URL encoding of the Wildflower app icon (128x128 PNG).
 *
 * Generated rather than a raw `import … from '*.png'` because tsdown/rolldown
 * (the `vp pack` pipeline) cannot load binary assets — it reads every import
 * as UTF-8 text. A data URL inlines the image into the JS bundle, which is
 * fine at ~22 KB for a single icon used in every surface's chrome.
 *
 * To regenerate after changing the source PNG, run from branding-react/:
 *
 *   printf "const iconSrc = 'data:image/png;base64,%s'\n\nexport default iconSrc\n" \
 *     "$(cat src/assets/app-icon.png | base64 | tr -d '\n')" > src/assets/app-icon.ts
 *
 * Then prepend this comment block.
 */
const iconSrc =
  'data:image/png;base64,'

export default iconSrc
