import { Schema } from 'effect'

import { AdministrativeGender } from '../../data-types/complex/administrative-gender.ts'
import * as DateSearchParam from '../search/date-search-param.ts'

const NumFromStr = Schema.NumberFromString.pipe(Schema.int(), Schema.greaterThanOrEqualTo(0))

const BoolFromStr = Schema.transform(Schema.Literal('true', 'false'), Schema.Boolean, {
  decode: (s) => s === 'true',
  encode: (b): 'true' | 'false' => {
    if (b) {
      return 'true'
    } else {
      return 'false'
    }
  },
})

/**
 * The `Patient` search parameters the typed client can express — paging plus
 * seven filters, a subset of FHIR R4 § Patient.search.
 *
 * @remarks
 * `identifier` is a FHIR `token` parameter (a bare value or the
 * `system|value` form, passed through as written; several comma-joined match
 * any of them) — how the importer finds the stored Patient an identity names.
 * `name`, `family` and `given` are FHIR `string` parameters: `name` is
 * matched against any part of the patient's names, `family` and `given`
 * against that part alone. They too are passed through as written, so
 * `a,b` matches either; a literal value goes through
 * `StringSearchParam.escape` first. The narrowings that remain are catalogued in
 * `fhir-r4/docs/Client Capabilities Reference.md`.
 */
const SearchParams = Schema.Struct({
  _count: Schema.optional(NumFromStr.pipe(Schema.between(0, 1000))),
  _cursor: Schema.optional(Schema.String),
  identifier: Schema.optional(Schema.String),
  name: Schema.optional(Schema.String),
  family: Schema.optional(Schema.String),
  given: Schema.optional(Schema.String),
  gender: Schema.optional(AdministrativeGender),
  active: Schema.optional(BoolFromStr),
  // FHIR `birthdate` search param maps to `Patient.birthDate`. One or more
  // `DateSearchParam` values, comma-joined to match any of them
  // (`DateSearchParam.AnyOf`): each an optional comparison prefix in front of
  // a date literal of any precision (`ge2000`, `2000-05`, `lt2000-05-01`),
  // carrying the period that precision implies.
  birthdate: Schema.optional(DateSearchParam.AnyOf),
})

type SearchParamsType = Schema.Schema.Type<typeof SearchParams>

export { SearchParams, type SearchParamsType }
